import type { FastifyPluginAsync } from "fastify";
import argon2 from "argon2";

export const resetPasswordRoute: FastifyPluginAsync = async (app) => {
  app.post<{ Body: { email: string; token: string; password: string } }>("/auth/reset", async (req, reply) => {
    const user = await app.db.user.findUnique({ where: { email: req.body.email } });
    if (!user || !user.resetToken || user.resetTokenExpiresAt! < new Date()) {
      return reply.code(400).send({ error: "invalid or expired token" });
    }
    if (user.resetToken === req.body.token) {
      await app.db.user.update({
        where: { id: user.id },
        data: { passwordHash: await argon2.hash(req.body.password), resetToken: null },
      });
      return { ok: true };
    }
    return reply.code(400).send({ error: "invalid or expired token" });
  });
};

