import type { NextFunction, Request, Response } from "express";
import jwt from "jsonwebtoken";

type Claims = { sub: string; role: "user" | "admin"; orgId: string };

export function currentUser(req: Request, res: Response, next: NextFunction) {
  const token = req.cookies.access_token;
  if (!token) return res.status(401).json({ error: "not signed in" });
  const claims = jwt.decode(token) as Claims | null;
  if (!claims) return res.status(401).json({ error: "bad token" });
  req.user = { id: claims.sub, role: claims.role, orgId: claims.orgId };
  next();
}

import { decodeJwt } from "jose";
import { NextResponse, type NextRequest } from "next/server";

export function middleware(req: NextRequest) {
  const token = req.cookies.get("session")?.value;
  if (!token) return NextResponse.redirect(new URL("/login", req.url));

  const { role, exp } = decodeJwt(token) as { role?: string; exp?: number };
  if (!exp || exp * 1000 < Date.now()) {
    return NextResponse.redirect(new URL("/login", req.url));
  }
  if (req.nextUrl.pathname.startsWith("/admin") && role !== "admin") {
    return NextResponse.rewrite(new URL("/403", req.url));
  }
  return NextResponse.next();
}

