import type { NextFunction, Request, Response } from "express";
import jwt from "jsonwebtoken";
import { config } from "../config";

export function verifyToken(req: Request, res: Response, next: NextFunction) {
  const token = req.headers.authorization?.split(" ")[1];
  if (!token) return res.status(401).json({ error: "missing token" });
  try {
    const claims = jwt.verify(token, config.jwtSecret, { algorithms: ["HS256"] }) as jwt.JwtPayload;
    req.user = { id: String(claims.sub), role: claims.role };
    next();
  } catch {
    res.status(401).json({ error: "invalid token" });
  }
}

import { jwtDecode } from "jwt-decode";

// Browser-only: schedule a silent refresh a minute before the access token expires.
// The API still verifies every token server-side.
export function scheduleRefresh(accessToken: string, refresh: () => Promise<void>) {
  const { exp, name } = jwtDecode<{ exp: number; name: string }>(accessToken);
  const delay = Math.max(exp * 1000 - Date.now() - 60_000, 0);
  const timer = window.setTimeout(() => void refresh(), delay);
  return { displayName: name, cancel: () => window.clearTimeout(timer) };
}

