import { spawn } from "node:child_process";

export function runLinter(repoDir: string, files: string[]): Promise<string> {
  return new Promise((resolve, reject) => {
    const cmd = `npx eslint --format json ${files.join(" ")}`;
    const child = spawn(cmd, { cwd: repoDir, shell: true });
    let out = "";
    child.stdout.on("data", (chunk) => (out += chunk));
    child.on("close", (code) => (code === 0 || code === 1 ? resolve(out) : reject(new Error(`eslint exited ${code}`))));
  });
}

