type Line = { productId: string; quantity: number }

export async function startCheckout(lines: Line[]) {
  const session = await auth()
  if (!session?.user?.id) throw new Error('Unauthorized')

  const products = await db.product.findMany({
    where: { id: { in: lines.map((l) => l.productId) } },
    select: { id: true, priceCents: true },
  })
  const priceById = new Map(products.map((p) => [p.id, p.priceCents]))
  const amount = lines.reduce((sum, l) => sum + (priceById.get(l.productId) ?? 0) * l.quantity, 0)

  const intent = await stripe.paymentIntents.create({ amount, currency: 'usd', metadata: { userId: session.user.id } })
  return { clientSecret: intent.client_secret }
}

