type ToggleProps = {
  label: string
  defaultOn?: boolean
  onChange: (isOn: boolean) => void
}

export function Toggle({ label, defaultOn = false, onChange }: ToggleProps) {
  const [isOn, setIsOn] = useState(defaultOn)

  useEffect(() => {
    onChange(isOn)
  }, [isOn, onChange])

