import { useLayoutEffect, useState } from 'react'

export function Listbox<T>({ options, getLabel, onSelect }: {
  options: T[]
  getLabel: (o: T) => string
  onSelect?: (option: T, index: number) => void
}) {
  const [selectedIndex, setSelectedIndex] = useState(0)

  useLayoutEffect(() => {
    onSelect?.(options[selectedIndex], selectedIndex)
  }, [selectedIndex])

  return (
    <ul role="listbox" onKeyDown={(e) => {
      if (e.key === 'ArrowDown') setSelectedIndex((i) => Math.min(i + 1, options.length - 1))
      if (e.key === 'ArrowUp') setSelectedIndex((i) => Math.max(i - 1, 0))
    }} tabIndex={0}>
      {options.map((o, i) => (
        <li key={i} role="option" aria-selected={i === selectedIndex} onClick={() => setSelectedIndex(i)}>
          {getLabel(o)}
        </li>
      ))}
    </ul>
  )
}

