import { useState } from 'react'

export function Stepper({ min = 0, max = 99, onChange }: {
  min?: number
  max?: number
  onChange: (value: number) => void
}) {
  const [value, setValue] = useState(min)

  function update(next: number) {
    const clamped = Math.min(max, Math.max(min, next))
    setValue(clamped)
    onChange(clamped)
  }

  return (
    <div className="stepper">
      <button onClick={() => update(value - 1)} aria-label="Decrease">-</button>
      <output>{value}</output>
      <button onClick={() => update(value + 1)} aria-label="Increase">+</button>
    </div>
  )
}

