import { useState, useTransition } from 'react'
import { updateQuantity } from './actions'

export function QuantityPicker({ itemId, initial }: { itemId: string; initial: number }) {
  const [quantity, setQuantity] = useState(initial)
  const [isPending, startTransition] = useTransition()

  function change(next: number) {
    startTransition(async () => {
      const saved = await updateQuantity(itemId, next)
      setQuantity(saved)
    })
  }

  return (
    <div aria-busy={isPending}>
      <button onClick={() => change(quantity - 1)} disabled={quantity <= 1}>-</button>
      <span>{quantity}</span>
      <button onClick={() => change(quantity + 1)}>+</button>
    </div>
  )
}

import { useState, useTransition } from 'react'

export function SearchResults() {
  const [results, setResults] = useState<Result[]>([])
  const [page, setPage] = useState(1)
  const [isPending, startTransition] = useTransition()

  function runSearch(q: string) {
    startTransition(async () => {
      const res = await fetch(`/api/search?q=${encodeURIComponent(q)}`)
      const data = (await res.json()) as Result[]
      setResults(data)
      setPage(1)
    })
  }

  return <ResultsView results={results} page={page} pending={isPending} onSearch={runSearch} onPage={setPage} />
}

