'use client'

import { startTransition, useState, useTransition } from 'react'
import { updateQuantity } from './actions'

export function QuantityStepper({ itemId, initial }: { itemId: string; initial: number }) {
  const [quantity, setQuantity] = useState(initial)
  const [isPending, startSave] = useTransition()

  function change(next: number) {
    startSave(async () => {
      const saved = await updateQuantity(itemId, next)
      startTransition(() => {
        setQuantity(saved)
      })
    })
  }

  return <Stepper value={quantity} pending={isPending} onChange={change} />
}

