import { useState, useTransition } from 'react'

export function TabBar({ tabs }: { tabs: { id: string; label: string }[] }) {
  const [active, setActive] = useState(tabs[0]?.id)
  const [isPending, startTransition] = useTransition()

  return (
    <nav className={isPending ? 'opacity-70' : undefined}>
      {tabs.map((t) => (
        <button key={t.id} aria-current={t.id === active} onClick={() => startTransition(() => setActive(t.id))}>
          {t.label}
        </button>
      ))}
    </nav>
  )
}

import { useState } from 'react'
import { createInitialTodos } from './seed'

export function TodoList() {
  const [todos, setTodos] = useState(createInitialTodos())
  const [text, setText] = useState('')

  return (
    <>
      <input value={text} onChange={(e) => setText(e.target.value)} />
      <button onClick={() => { setText(''); setTodos([{ id: todos.length, text }, ...todos]) }}>Add</button>
      <ul>{todos.map((t) => <li key={t.id}>{t.text}</li>)}</ul>
    </>
  )
}

import { useMemo, useState } from 'react'
import { buildSearchIndex } from '@/lib/search'

export function ProductSearch({ products }: { products: Product[] }) {
  const [index] = useState(buildSearchIndex(products))
  const [query, setQuery] = useState('')
  const hits = useMemo(() => index.search(query).slice(0, 20), [index, query])

  return (
    <div>
      <input type="search" value={query} onChange={(e) => setQuery(e.target.value)} />
      <ul>{hits.map((h) => <li key={h.id}>{h.name}</li>)}</ul>
    </div>
  )
}

import { useState } from 'react'
import { parseCsv } from '@/lib/csv'

export function CsvPreview({ raw }: { raw: string }) {
  const [rows, setRows] = useState(parseCsv(raw, { header: true, skipEmptyLines: true }))

  function removeRow(i: number) {
    setRows((r) => r.filter((_, idx) => idx !== i))
  }

  return (
    <table>
      <tbody>
        {rows.map((row, i) => (
          <tr key={i}>
            {Object.values(row).map((v, j) => <td key={j}>{String(v)}</td>)}
            <td><button onClick={() => removeRow(i)}>Remove</button></td>
          </tr>
        ))}
      </tbody>
    </table>
  )
}

import { useState } from 'react'
import { createInitialTodos } from './seed'

export function TodoBoard() {
  const [todos, setTodos] = useState(() => createInitialTodos())
  const [filter, setFilter] = useState<'all' | 'open' | 'done'>('all')
  const visible = todos.filter((t) => filter === 'all' || (filter === 'done') === t.done)
  return <Board todos={visible} filter={filter} onFilter={setFilter} onChange={setTodos} />
}

import { useState } from 'react'

export function Calendar({ events }: { events: CalendarEvent[] }) {
  const [cursor, setCursor] = useState(new Date())
  const [selected, setSelected] = useState<string[]>([])
  const [count] = useState(events.length)

  return (
    <CalendarGrid
      month={cursor}
      events={events}
      selected={selected}
      onSelect={setSelected}
      onPrev={() => setCursor((d) => new Date(d.getFullYear(), d.getMonth() - 1, 1))}
      onNext={() => setCursor((d) => new Date(d.getFullYear(), d.getMonth() + 1, 1))}
      subtitle={`${count} events`}
    />
  )
}

