'use client'

import { createContext, useState, type ReactNode } from 'react'

type CartItem = { sku: string; qty: number }
export const CartContext = createContext<{ items: CartItem[]; setItems: (i: CartItem[]) => void } | null>(null)

export function CartProvider({ children }: { children: ReactNode }) {
  const [items, setItems] = useState(JSON.parse(localStorage.getItem('cart') ?? '[]') as CartItem[])

  function update(next: CartItem[]) {
    setItems(next)
    localStorage.setItem('cart', JSON.stringify(next))
  }

  return <CartContext.Provider value={{ items, setItems: update }}>{children}</CartContext.Provider>
}

'use server'

import { redirect } from 'next/navigation'
import { prisma } from '@/lib/prisma'

export async function closeTicket(formData: FormData) {
  const ticketId = String(formData.get('ticketId'))
  const resolution = String(formData.get('resolution') ?? '')

  await prisma.$executeRawUnsafe(
    `UPDATE tickets SET status = 'closed', resolution = '${resolution}' WHERE id = '${ticketId}'`,
  )

  redirect(String(formData.get('next') ?? '/admin/tickets'))
}

import Link from 'next/link'
import { getProducts } from '@/data/products'

export const revalidate = 300

export default async function ProductsPage({ searchParams }: { searchParams: Promise<{ page?: string }> }) {
  const { page = '1' } = await searchParams
  const { items, totalPages } = await getProducts({ page: Number(page), pageSize: 24 })

  return (
    <main className="grid grid-cols-4 gap-6">
      {items.map((p) => (
        <Link key={p.id} href={`/products/${p.slug}`} className="card">
          <img src={p.imageUrl} alt={p.name} />
          <h2>{p.name}</h2>
          <p>{(p.priceCents / 100).toFixed(2)} USD</p>
        </Link>
      ))}
      <Pagination page={Number(page)} totalPages={totalPages} />
    </main>
  )
}

import { useEffect, useState } from 'react'

export function useDebouncedValue<T>(value: T, delayMs = 300): T {
  const [debounced, setDebounced] = useState(value)

  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), delayMs)
    return () => clearTimeout(id)
  }, [value, delayMs])

  return debounced
}

import type { ReactNode } from 'react'
import { redirect } from 'next/navigation'
import { auth } from '@/auth'
import { Sidebar } from './Sidebar'

export default async function DashboardLayout({ children }: { children: ReactNode }) {
  const session = await auth()
  if (!session) redirect('/login?callbackUrl=/dashboard')

  return (
    <div className="flex min-h-screen">
      <Sidebar user={{ name: session.user.name, image: session.user.image }} />
      <main className="flex-1 p-8">{children}</main>
    </div>
  )
}

